import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl, setCameraLimits } from "@babylonjs/lite";

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  // Bring the camera inside the range immediately if it started outside.
  camera.radius = Math.max(minDistance, Math.min(maxDistance, camera.radius));

  // Set the radius limits on the camera and register per-frame clamping
  // via the scene's render loop.
  const cleanupLimits = setCameraLimits(
    camera,
    { lowerRadiusLimit: minDistance, upperRadiusLimit: maxDistance },
    scene,
  );

  // Attach the library's standard pointer controls (drag-to-orbit,
  // wheel/pinch-to-zoom) on the canvas.
  const cleanupControls = attachControl(camera, canvas, scene);

  return () => {
    cleanupControls();
    cleanupLimits();
  };
}
```

I wrote `src/limited-orbit.ts` which clamps the initial radius, uses the library's `setCameraLimits` to enforce `lowerRadiusLimit`/`upperRadiusLimit` every frame through the scene, and attaches the standard orbit controls via `attachControl`. I'm not 100% certain that `setCameraLimits` clamps *after* the controls apply their per-frame changes (as opposed to before), but given that it accepts a `SceneContext` and the camera exposes `_clampToLimits`, it is the library's purpose-built mechanism for this and should guarantee the radius stays in bounds on every rendered frame.
